#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/gitleaks/tasks/code-sec-gitleaks.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Scan for secrets with gitleaks"
# MISE tools={uv="latest", python="3.14"}

# USAGE flag "--debug" help="emit debug logs"
# USAGE flag "--staged" help="scan only the staged changes (for the pre-commit hook)"

import os
import shutil
import subprocess
import sys
import tempfile

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def copy_known_files(root, scan_dir):
  """Copy the files that git knows about in root into scan_dir with tar, and
  return the code of the tar that extracts them."""
  # A tracked file that is deleted in the working tree is not on disk.
  listed = subprocess.run(
    ["git", "ls-files", "-z", "--cached", "--others", "--exclude-standard"],
    cwd=root,
    stdout=subprocess.PIPE,
    check=False,
  ).stdout
  names = b""
  for name in listed.split(b"\0"):
    if not name:
      continue
    path = os.path.join(os.fsencode(root), name)
    if os.path.isfile(path) and not os.path.islink(path):
      names += name + b"\0"
  create = subprocess.Popen(
    ["tar", "--null", "-T", "-", "-cf", "-"], cwd=root, stdin=subprocess.PIPE, stdout=subprocess.PIPE
  )
  extract = subprocess.Popen(["tar", "-xf", "-", "-C", scan_dir], stdin=create.stdout)
  create.stdout.close()
  create.stdin.write(names)
  create.stdin.close()
  code = extract.wait()
  create.wait()
  return code


def main():
  root = os.environ["MISE_PROJECT_ROOT"]
  flags = ["--verbose"] if os.environ.get("usage_debug", "false") == "true" else []

  # The hook scans what is staged: the commit is the content that leaves the
  # machine.
  if os.environ.get("usage_staged", "false") == "true":
    result = helpers.tool(
      "gitleaks", "git", "--staged", "--config", f"{root}/.config/gitleaks.toml", "--redact", "50", *flags
    )
    return result.returncode

  # gitleaks reads no .gitignore: `gitleaks dir` scans every file, also the
  # ignored ones such as graphify-out/ and node_modules/. It takes one path
  # only. Thus copy the files that git knows about (tracked, and new files that
  # are not ignored) into a temporary folder, and scan that folder once. The
  # report paths stay relative to the repository.
  helpers.print_subheader("Scanning the files for secrets with gitleaks ...")
  scan_dir = tempfile.mkdtemp(prefix="code-sec.", dir=os.environ.get("TMPDIR") or "/tmp")
  try:
    code = copy_known_files(root, scan_dir)
    if code != 0:
      return code
    # The gitleaks of this repository, found from the repository root.
    found = subprocess.run(["mise", "which", "gitleaks"], cwd=root, stdout=subprocess.PIPE, text=True, check=False)
    if found.returncode != 0:
      return found.returncode
    gitleaks = found.stdout.rstrip("\n")
    result = subprocess.run(
      [gitleaks, "dir", ".", "--config", f"{root}/.config/gitleaks.toml", "--redact", "50", *flags],
      cwd=scan_dir,
      check=False,
    )
    return result.returncode
  finally:
    shutil.rmtree(scan_dir, ignore_errors=True)


if __name__ == "__main__":
  sys.exit(main())
